function getUniqueCustomEmojisFromMessage(message) {
	const docIds = [];
	const iterateEntities = (entities) => {
		if (!entities) return;
		const filtered = entities.filter((entity) => entity._ === "messageEntityCustomEmoji" && !entity.w);
		docIds.push(...filtered.map((entity) => entity.document_id));
	};
	iterateEntities(message.entities);
	const richMessage = message.rich_message;
	if (richMessage) iterateEntities(flattenRichMessageContent(richMessage).entities);
	const reactions = message.reactions;
	if (reactions) {
		const results = reactions.results.filter((reactionCount) => reactionCount.reaction._ === "reactionCustomEmoji");
		docIds.push(...results.map((reactionCount) => reactionCount.reaction.document_id));
	}
	const poll = message.media?.poll;
	if (poll) {
		iterateEntities(poll.question.entities);
		poll.answers.forEach((answer) => {
			iterateEntities(answer.text.entities);
		});
	}
	const todo = message.media?.todo;
	if (todo) {
		iterateEntities(todo.title.entities);
		todo.list.forEach((item) => {
			iterateEntities(item.title.entities);
		});
	}
	return filterUnique(docIds);
}
